const TESTS_IT_VOLL = [
  {
    title: 'VOLLPRÜFUNG 1 – Datenschutz-Audit eines KMU',
    duration: 240, isFull: true,
    description: 'Realistische 4h-IT-Prüfung: Datenschutz, Verträge, Sicherheitskonzept, Verschlüsselung.',
    questions: [
      { type: 'open', q: 'Eine Werbeagentur (15 Mitarbeitende) bittet dich um Bewertung ihrer DSGVO-Konformität. Liste 8 zentrale Prüfpunkte auf.', model: '1) Verfahrensverzeichnis (Art. 30) vorhanden und aktuell. 2) AV-Verträge mit Dienstleistern (Cloud, Mail, Newsletter). 3) Datenschutzerklärung auf Website (Art. 13/14). 4) Cookie-Banner mit aktiver Einwilligung. 5) Datenschutzbeauftragter benannt (über 20 MA Pflicht – hier optional, aber sinnvoll). 6) TOMs dokumentiert (Verschlüsselung, Backups, Berechtigungen). 7) Mitarbeiter-Schulungen + Verschwiegenheitsverpflichtung. 8) Notfall-/Datenpannen-Prozess (72h-Meldung). 9) Mitarbeiterdaten korrekt verarbeitet (Anwesenheit, Kontaktdaten). 10) Klare Löschkonzepte (Speicherbegrenzung).', points: 10 },
      { type: 'mc', q: 'Welche Rechtsgrundlage trifft am besten zu, wenn die Agentur Newsletter an Bestandskunden verschickt?', options: ['Art. 6 Abs. 1 lit. a DSGVO (Einwilligung)', 'Art. 6 Abs. 1 lit. b DSGVO (Vertragserfüllung)', 'Art. 6 Abs. 1 lit. f DSGVO + § 7 Abs. 3 UWG (Bestandskunden-Werbung)', 'Art. 6 Abs. 1 lit. e DSGVO (öffentl. Aufgabe)'], correct: 2, points: 4, explanation: '§ 7 Abs. 3 UWG erlaubt unter Bedingungen Werbung an Bestandskunden ohne ausdrückliche Einwilligung – ähnlich produkte, beim Erwerb hingewiesen, jederzeit widersprechbar.' },
      { type: 'open', q: 'Erkläre den Unterschied zwischen symmetrischer und asymmetrischer Verschlüsselung mit je einem Beispiel und Anwendungszweck.', model: 'Symmetrisch: Ein Schlüssel zum Ver- und Entschlüsseln. Beispiel: AES (256 Bit). Anwendung: Festplatten-Verschlüsselung (BitLocker), VPN-Daten, ZIP-Passwortschutz. Vorteil: schnell. Problem: Schlüsselaustausch. Asymmetrisch: Schlüsselpaar (öffentlich + privat). Was mit Public verschlüsselt, kann nur Private entschlüsseln. Beispiel: RSA. Anwendung: HTTPS-Zertifikate, digitale Signaturen, sicherer Austausch von Sitzungsschlüsseln. Vorteil: kein vorab-Schlüsselaustausch nötig. Nachteil: rechenintensiv. Praxis: Hybrid (asym. für Schlüsseltausch, dann sym. für Datenverkehr).', points: 10 },
      { type: 'open', q: 'Erkläre den Diffie-Hellman-Schlüsselaustausch in eigenen Worten + warum er sicher ist.', model: 'Beide Parteien einigen sich auf öffentliche Werte (Primzahl p, Basis g) und wählen je einen geheimen Wert (a bzw. b). Sie berechnen daraus öffentliche Werte A=g^a mod p und B=g^b mod p und tauschen sie aus. Beide rechnen dann den gemeinsamen Schlüssel K = B^a mod p = A^b mod p. Sicher, weil ein Angreifer A, B, g, p kennt, aber nicht a oder b berechnen kann (diskreter Logarithmus ist mathematisch schwer). Wichtig: ohne Authentifizierung anfällig für Man-in-the-Middle.', points: 8 },
      { type: 'open', q: 'Beschreibe den Caesar-Code mit Schlüssel 4. Verschlüssele "MEDIEN".', model: 'Cäsar verschiebt jeden Buchstaben um eine feste Zahl im Alphabet. Mit Schlüssel 4: A→E, B→F, ... M→Q, E→I, D→H, I→M, E→I, N→R. Ergebnis: QIHMIR. Sehr unsicher (nur 25 mögliche Schlüssel, in Sekunden zu knacken).', points: 5 },
      { type: 'open', q: 'Was sind Hash-Funktionen? Nenne 3 Eigenschaften und 3 Anwendungsfälle.', model: 'Hash-Funktion = Einweg-Funktion, die aus beliebigem Input einen festen Fingerabdruck erzeugt. Eigenschaften: 1) Deterministisch (gleicher Input → gleicher Output). 2) Einweg (nicht zurückrechenbar). 3) Lawineneffekt (kleine Änderung → komplett anderer Hash). 4) Kollisionsresistent. Anwendungen: 1) Passwörter speichern (mit Salt). 2) Datei-Integrität (Checksumme). 3) Digitale Signaturen. 4) Blockchain. Verfahren: SHA-256, bcrypt (für Passwörter). MD5/SHA-1 sind unsicher.', points: 8 },
      { type: 'open', q: 'Du sollst eine sichere Backup-Strategie für die Agentur entwickeln. Erkläre die 3-2-1-Regel und konkretisiere sie für diesen Fall.', model: '3-2-1: 3 Datenkopien, 2 verschiedene Medien, 1 Off-Site. Konkret: 1 Original auf NAS im Büro. 2. Kopie täglich automatisch auf zweite NAS oder externe Festplatte (anderes Medium). 3. Kopie wöchentlich verschlüsselt in Cloud (Off-Site, schützt vor Brand/Diebstahl). Zusätzlich: 1 Offline-Backup (rotierend ext. HDD, nach Backup abstecken) als Schutz vor Ransomware. Wöchentlich Vollbackup, täglich inkrementell. Backups regelmäßig TESTEN!', points: 8 },
      { type: 'mc', q: 'Was ist KEIN Pflichtbestandteil eines Impressums nach DDG?', options: ['Anschrift inkl. Postfach reicht aus', 'Kontakt (mind. E-Mail)', 'Vor- und Zuname / Firmenname', 'Bei eingetragenen Unternehmen: Handelsregister + Nummer'], correct: 0, points: 4, explanation: 'Postfach reicht NICHT – es muss eine ladungsfähige Anschrift sein (Straße + Hausnummer + PLZ + Ort).' },
      { type: 'open', q: 'Mit welchen Maßnahmen schützt du das Klienten-Portal vor Brute-Force-Angriffen? Mind. 5.', model: '1) Lange, komplexe Passwörter erzwingen (min 12 Zeichen). 2) 2-Faktor-Authentifizierung (TOTP-App oder SMS, besser App). 3) Account-Lockout nach 5-10 Fehlversuchen. 4) Rate-Limiting / IP-Throttling. 5) CAPTCHA bei verdächtigem Verhalten. 6) Login-Versuche loggen + Monitoring. 7) Bcrypt/Argon2 für Passwort-Hashing in Datenbank. 8) Niemals Klartext-Passwörter speichern. 9) Login per Magic-Link als Alternative.', points: 10 },
      { type: 'open', q: 'Eine Mitarbeiterin meldet eine Phishing-E-Mail, die sie geöffnet UND einen Anhang heruntergeladen hat. Was sind deine sofortigen Maßnahmen? Schritt-für-Schritt.', model: '1) Sofort PC vom Netzwerk trennen (LAN abziehen, WLAN aus). 2) IT/Datenschutzbeauftragten informieren. 3) System nicht abschalten (forensische Analyse evtl. nötig). 4) Mitarbeiter befragen: Was wurde geklickt/eingegeben? 5) Wenn Zugangsdaten eingegeben: alle betroffenen Passwörter SOFORT ändern, 2FA prüfen. 6) Antivirus-Vollscan auf Gerät. 7) Logs prüfen auf Datenabfluss. 8) Bei begründetem Verdacht auf Datenpanne: 72h-Meldung an Aufsichtsbehörde (DSGVO Art. 33). 9) Ggf. Betroffene informieren. 10) Vorfall dokumentieren und Schulung verbessern.', points: 10 },
      { type: 'mc', q: 'Welche Schutzdauer gilt im Urheberrecht für Werke der bildenden Kunst?', options: ['25 Jahre nach Erstveröffentlichung', '50 Jahre nach Tod des Urhebers', '70 Jahre nach Tod des Urhebers', 'Unbegrenzt'], correct: 2, points: 3 },
      { type: 'open', q: 'Erkläre die 7 Schichten des OSI-Modells mit je einem Beispiel.', model: '7. Anwendung (HTTP/HTTPS, Mail-Programm). 6. Darstellung (JPEG, ASCII, Verschlüsselung). 5. Sitzung (Verbindungsmanagement). 4. Transport (TCP, UDP). 3. Vermittlung (IP, Router). 2. Sicherung (Ethernet, MAC, Switch). 1. Bitübertragung (Kabel, Funk). Eselsbrücke: Alle Programmierer Sehen Tatsächlich Nur Datenmüll Bits.', points: 8 },
      { type: 'open', q: 'Erkläre den Ablauf einer HTTPS-Verbindung (vereinfacht).', model: '1) Client (Browser) öffnet Verbindung zu Server auf Port 443. 2) TLS-Handshake: Server sendet Zertifikat (mit öffentlichem RSA-Schlüssel). 3) Browser prüft Zertifikat bei Certificate Authority (Vertrauenskette). 4) Mit asymmetrischer Krypto (oder besser: Diffie-Hellman) wird ein gemeinsamer Sitzungsschlüssel erzeugt/ausgetauscht. 5) Ab jetzt verschlüsselte Kommunikation mit symmetrischem Verfahren (AES). 6) HMAC sichert Integrität jeder Nachricht. → Hybride Verschlüsselung kombiniert Sicherheit (asym.) und Performance (sym.).', points: 10 },
      { type: 'open', q: 'Erstelle eine Liste der TOMs (technische und organisatorische Maßnahmen), die du der Agentur empfiehlst. Mind. 8.', model: 'Technisch: 1) Festplattenverschlüsselung (BitLocker/FileVault). 2) Verschlüsselte Mails für sensible Daten. 3) Firewall + Virenschutz aktuell. 4) Update-Management. 5) Berechtigungs-Konzept (Need-to-know). 6) Backup-Strategie (3-2-1). 7) 2FA für alle wichtigen Konten. 8) Logging/Monitoring. Organisatorisch: 9) Verschwiegenheitsverpflichtung. 10) Mitarbeiter-Schulungen 2x/Jahr. 11) Clean-Desk-Policy. 12) Akten-Vernichtung nach DIN 66399. 13) Zugangskontrolle (Schlüssel/Chipkarten). 14) Notfallplan dokumentiert. 15) Verfahrensverzeichnis.', points: 12 },
    ]
  },
  {
    title: 'VOLLPRÜFUNG 2 – Sicherheitskonzept Online-Shop',
    duration: 240, isFull: true,
    description: 'Recht, Verschlüsselung, Angriffsabwehr, Compliance für einen Mode-Online-Shop.',
    questions: [
      { type: 'open', q: 'Welche rechtlichen Pflicht-Texte braucht ein deutscher Online-Shop? Mind. 8 mit kurzer Erläuterung.', model: '1) Impressum (DDG §5). 2) Datenschutzerklärung (DSGVO Art. 13). 3) AGB (Allgemeine Geschäftsbedingungen). 4) Widerrufsbelehrung + Muster-Widerrufsformular (BGB §312g). 5) Versandkosten + Lieferzeit klar. 6) Cookie-Hinweis (TTDSG/DSGVO). 7) Hinweise zur Verbraucherstreitbeilegung (§ 36 VSBG). 8) Preisangaben gemäß PAngV (inkl. MwSt., Grundpreis). 9) Zahlungspflichtig-Bestellen-Button (BGB §312j). 10) Bestätigungs-Mail nach Bestellung.', points: 10 },
      { type: 'open', q: 'Vergleiche AES und RSA: jeweils Funktionsprinzip, Schlüssellängen, typische Anwendung, Vor-/Nachteile.', model: 'AES: symmetrisch, ein Schlüssel. 128/192/256 Bit. Anwendung: Datenverschlüsselung (HTTPS-Daten, BitLocker). Vorteile: sehr schnell, hardwarebeschleunigt. Nachteil: Schlüsselaustausch ist Problem.\nRSA: asymmetrisch, Schlüsselpaar. Heute mind. 2048, besser 4096 Bit. Anwendung: TLS-Zertifikate, digitale Signaturen, Schlüsselaustausch. Vorteile: kein vorab-Schlüsselaustausch nötig. Nachteile: langsam (~1000x langsamer als AES), anfällig gegen Quantencomputer.\nIn der Praxis: Hybrid – RSA für Schlüsselaustausch, AES für eigentliche Daten.', points: 10 },
      { type: 'open', q: 'Was ist eine SQL-Injection? Wie schützt man sich? Beispielcode.', model: 'SQL-Injection: Angreifer schleust SQL-Code in eine Eingabe ein, der dann auf der Datenbank ausgeführt wird. Beispiel: Login-Feld "admin\' OR 1=1 --" → Login-Query wird umgeschrieben und Angreifer ist eingeloggt. Schutz: 1) Prepared Statements / Parameterized Queries (Werte separat vom SQL-Code). 2) ORM (Object-Relational-Mapping) verwenden. 3) Input-Validierung (Whitelist statt Blacklist). 4) DB-User mit minimalen Rechten. 5) Fehlermeldungen nicht ausgeben. 6) WAF (Web Application Firewall).\nBeispiel sicher (PHP/PDO): \n$stmt = $pdo->prepare("SELECT * FROM users WHERE email = ?");\n$stmt->execute([$email]);', points: 10 },
      { type: 'open', q: 'Was ist Cross-Site-Scripting (XSS)? 3 Arten + Schutz.', model: 'XSS: Angreifer schleust JavaScript in eine Webseite ein, das im Browser anderer Nutzer ausgeführt wird – stiehlt Cookies, Session, manipuliert Inhalte.\nArten: 1) Reflected (über URL-Parameter, einmalig). 2) Stored (im DB gespeichert, z.B. in Kommentaren, dauerhaft). 3) DOM-based (clientseitig, ohne Server). Schutz: 1) Output-Encoding (HTML-Escape). 2) Content-Security-Policy (CSP-Header). 3) HttpOnly + Secure auf Cookies. 4) Input validieren. 5) Vertrauenswürdige Frameworks nutzen (React, Vue – escapen automatisch). 6) Niemals innerHTML mit unsicherem Input.', points: 8 },
      { type: 'mc', q: 'Welcher Cookie-Banner ist DSGVO-konform?', options: ['"Wenn Sie weiter surfen, akzeptieren Sie alle Cookies"', 'Banner mit "Alle akzeptieren" und gleichwertigem "Alle ablehnen"', 'Banner nur mit "Alle akzeptieren"-Button', 'Banner unten mit "Verstanden"-Knopf, der nichts beeinflusst'], correct: 1, points: 4, explanation: 'Aktive Einwilligung erforderlich, "Ablehnen" muss gleichwertig sichtbar/zugänglich sein. Voreinstellungen sind verboten.' },
      { type: 'open', q: 'Wie schützt der Shop sich vor DDoS-Angriffen? Mind. 5 Maßnahmen.', model: '1) CDN mit DDoS-Schutz (Cloudflare, Akamai) vorschalten. 2) Rate-Limiting auf Webserver-Ebene. 3) Web Application Firewall (WAF) für Filterung. 4) Auto-Scaling der Infrastruktur (Cloud) bei Lastspitzen. 5) Monitoring + Alarmierung bei Anomalien. 6) Geo-Blocking unerwünschter Regionen. 7) BGP-Routing-Tricks bei großen Angriffen (mit ISP). 8) Notfallplan inkl. Kommunikation mit Kunden.', points: 8 },
      { type: 'open', q: 'Berechne mit Cäsar-Chiffre und Schlüssel 7: Verschlüssele "ANGRIFF". Beschreibe Schritte.', model: 'Schritt: jeden Buchstaben um 7 verschieben. A(0)+7=H(7). N(13)+7=U(20). G(6)+7=N(13). R(17)+7=Y(24). I(8)+7=P(15). F(5)+7=M(12). F(5)+7=M(12). Ergebnis: HUNYPMM. Bei Überlauf über Z hinaus: mod 26 anwenden (z.B. X(23)+7=30 mod 26 = 4 = E).', points: 5 },
      { type: 'open', q: 'PCI-DSS: Was ist das und welche Anforderungen gibt es für den Shop?', model: 'PCI-DSS = Payment Card Industry Data Security Standard. Pflicht für alle, die Kreditkartendaten verarbeiten/speichern/übertragen. Hauptanforderungen: 1) Sichere Netzwerke (Firewall, kein Standard-Passwort). 2) Karteninhaberdaten schützen (Verschlüsselung, eingeschränkter Zugriff). 3) Verschlüsselte Übertragung (HTTPS). 4) Antiviren + Patches aktuell. 5) Strikte Zugriffsverwaltung (Need-to-know). 6) Regelmäßige Pentests + Audits. 7) Sicherheitsrichtlinien dokumentiert. Praxis: meist über Payment-Provider (Stripe, PayPal) statt selbst speichern – dann reduziert sich Anforderung erheblich.', points: 8 },
      { type: 'open', q: 'Erkläre die Funktionsweise einer digitalen Signatur (mit RSA).', model: '1) Sender erstellt Hash der Nachricht (z.B. SHA-256). 2) Sender verschlüsselt diesen Hash mit seinem PRIVATEN Schlüssel → das ist die Signatur. 3) Sender sendet Nachricht + Signatur an Empfänger. 4) Empfänger entschlüsselt Signatur mit dem ÖFFENTLICHEN Schlüssel des Senders → erhält den Hash. 5) Empfänger berechnet selbst den Hash der Nachricht. 6) Wenn beide Hashes gleich → Nachricht ist authentisch UND unverändert. Sichert: Authentizität (nur der Inhaber des Privaten Schlüssels konnte signieren) + Integrität (Hash würde sonst abweichen).', points: 10 },
      { type: 'open', q: 'Was ist Ransomware? Wie schützt man sich? Was tun, wenn es passiert?', model: 'Ransomware: Schadsoftware, die Daten verschlüsselt und Lösegeld fordert. Schutz: 1) Aktuelle Backups (mind. 1 OFFLINE!). 2) Updates regelmäßig. 3) E-Mail-Filter und Schulung gegen Phishing. 4) Macros in Office deaktivieren. 5) EDR/Antivirus mit Verhaltensanalyse. 6) Eingeschränkte Benutzerrechte. 7) Netzwerk-Segmentierung. Im Fall: 1) Sofort isolieren (Netzwerk trennen). 2) NICHT zahlen (kein Garantie + finanziert Täter). 3) Polizei + IT-Forensik einschalten. 4) Aus Backup wiederherstellen. 5) Datenpanne nach DSGVO Art. 33 melden. 6) Lessons learned.', points: 8 },
      { type: 'mc', q: 'Welche Aussage zu IPv6 ist FALSCH?', options: ['IPv6-Adresse ist 128 Bit lang', 'IPv6 enthält IPsec für Verschlüsselung', 'IPv6 hat ca. 4,3 Mrd. Adressen', 'IPv6 wird in Hexadezimalblöcken mit Doppelpunkten geschrieben'], correct: 2, points: 3, explanation: '4,3 Mrd. ist IPv4 (2^32). IPv6 hat 2^128 = praktisch unbegrenzt.' },
      { type: 'open', q: 'Newsletter-Versand: Welche rechtlichen Anforderungen + Double-Opt-In erklären.', model: 'Anforderungen: aktive Einwilligung (Art. 6 Abs. 1 lit. a DSGVO + § 7 UWG). Ausnahme: bestehender Kundenkontakt mit ähnlichen Produkten + jederzeit widersprechbar (§ 7 Abs. 3 UWG). Pflicht: jederzeitiger Widerruf, klarer Absender, Kennzeichnung als Werbung, Impressum.\nDouble-Opt-In: 1) Nutzer trägt E-Mail in Formular ein. 2) System sendet Bestätigungsmail mit Link. 3) Erst nach Klick auf Link wird Anmeldung aktiv. → Beweis, dass tatsächlich der Inhaber zugestimmt hat. Logs (IP, Zeit, Klick) speichern als Nachweis.', points: 8 },
      { type: 'open', q: 'Erkläre Salt + Pepper bei Passwort-Hashing. Warum wichtig?', model: 'Salt: Zufalls-String, der vor dem Hashen ans Passwort angehängt wird. JEDER Nutzer hat eigenes Salt. Salt wird (offen) in DB gespeichert. → Schützt vor Rainbow-Tables (vorberechnete Hash-Listen). Bei zwei gleichen Passwörtern entstehen unterschiedliche Hashes.\nPepper: zusätzlicher geheimer String, NICHT in DB, sondern z.B. in Server-Config. → Wenn Datenbank gestohlen wird, fehlt der Pepper. Angreifer kann Hashes nicht knacken, ohne auch Server-Zugriff zu haben.\nKombiniert mit langsamen Hashfunktionen (bcrypt, Argon2): macht Brute-Force unwirtschaftlich.', points: 8 },
    ]
  },
  {
    title: 'VOLLPRÜFUNG 3 – Selbstständigkeit als Mediengestalter',
    duration: 240, isFull: true,
    description: 'Selbstständigkeit, Verträge, Steuern, Urheberrecht, Kundenkommunikation, Datenschutz im Auftragsverhältnis.',
    questions: [
      { type: 'open', q: 'Was musst du vor Beginn deiner selbstständigen Tätigkeit als Mediengestalter erledigen? Mind. 6 Schritte.', model: '1) Gewerbe anmelden (Gewerbeamt) oder Freiberufler-Status prüfen (Finanzamt – Mediengestalter sind oft freiberuflich, hängt von Tätigkeit ab). 2) Steuerlicher Erfassungsbogen Finanzamt (Steuernummer, Umsatzsteuer-Wahl Kleinunternehmer §19 oder Regelbesteuerung). 3) Krankenversicherung klären (gesetzlich freiwillig oder privat). 4) Künstlersozialkasse (KSK) prüfen, falls überwiegend künstlerisch tätig. 5) Berufshaftpflicht-Versicherung abschließen. 6) Bankkonto (Geschäftskonto empfohlen). 7) Buchhaltungs-Software (z.B. Lexoffice, sevDesk). 8) AGB + Datenschutzerklärung erstellen. 9) Impressum für Website. 10) Logo + CI für eigenen Auftritt.', points: 10 },
      { type: 'open', q: 'Erkläre den Unterschied zwischen Gewerbe und Freiberufler-Status.', model: 'Freiberufler (§ 18 EStG): "Katalogberufe" wie Künstler, Designer, Journalisten, Architekten. Vorteile: keine Gewerbesteuer, Einnahmen-Überschuss-Rechnung möglich, keine IHK-Zwangsmitgliedschaft, keine Bilanzpflicht. Anmeldung nur beim Finanzamt.\nGewerbe (§ 15 EStG): Handel, Handwerk, Dienstleistungen außerhalb der Katalogberufe. Pflichten: Gewerbeschein, Gewerbesteuer (ab Freibetrag 24.500 €), IHK-Mitgliedschaft, ggf. Bilanzpflicht ab Größe.\nMediengestalter: Grenze unscharf. Reine kreative Tätigkeit (Layouts, Konzepte) → meist Freiberufler. Reine technische Umsetzung, Druckhandel → eher Gewerbe. Im Zweifel: Finanzamt-Anfrage.', points: 8 },
      { type: 'open', q: 'Erkläre Nutzungsrechte vs. Urheberrechte mit Beispiel.', model: 'Urheberrecht: kann nicht übertragen werden (§ 29 UrhG). Bleibt immer beim Schöpfer. Beispiel: Du gestaltest Logo, du bleibst Urheber.\nNutzungsrechte: das, was übertragen wird. § 31 UrhG. Können einfach (mehrere Lizenznehmer) oder ausschließlich (nur einer) sein. Können räumlich, zeitlich, inhaltlich beschränkt sein.\nBeispiel Logo: Kunde erhält ausschließliches, zeitlich unbegrenztes, weltweites Nutzungsrecht für Print + Web + Bekleidung. Erweiterungen (z.B. Merchandising) gegen Aufpreis. Verwendung als Vorlage für andere Logos: NICHT übertragen. Wichtig: schriftlich klar definieren!', points: 10 },
      { type: 'open', q: 'Welche Pflichtangaben muss eine Rechnung enthalten? Mind. 8 Punkte (§ 14 UStG).', model: '1) Vollständiger Name + Anschrift Leistungserbringer. 2) Vollständiger Name + Anschrift Leistungsempfänger. 3) Steuernummer ODER USt-IdNr. 4) Ausstellungsdatum. 5) Fortlaufende Rechnungsnummer (eindeutig). 6) Menge + Art (Bezeichnung) der Leistung. 7) Zeitpunkt der Leistung (oder: "im Monat X"). 8) Nettobetrag (aufgeschlüsselt nach Steuersätzen). 9) Steuersatz + Steuerbetrag (oder Hinweis auf Steuerbefreiung, z.B. § 19 UStG bei Kleinunternehmer). 10) Bruttobetrag.\nKleinbetragsrechnung bis 250 € brutto: vereinfachte Pflichtangaben (Name+Anschrift Leister, Datum, Leistung, Bruttobetrag, Steuersatz).', points: 8 },
      { type: 'open', q: 'Kleinunternehmer-Regelung (§ 19 UStG): Voraussetzungen + Vor- und Nachteile.', model: 'Voraussetzungen: Vorjahres-Umsatz max. 22.000 € + erwarteter laufender Umsatz max. 50.000 €.\nFolge: Keine Umsatzsteuer auf Rechnungen ausweisen, Hinweis "Kein Ausweis von USt gemäß § 19 UStG". Keine USt-Voranmeldung.\nVorteile: einfacher (keine USt-Rechnung), günstiger für Privat-Kunden (Endpreis niedriger).\nNachteile: kein Vorsteuer-Abzug auf Einkäufe (kann teuer werden bei großen Anschaffungen). B2B-Kunden ist USt egal (sie ziehen sie eh ab) → da hat man keinen Vorteil. Bei Wachstum: Wechsel oft sinnvoll.', points: 8 },
      { type: 'open', q: 'Was sollte ein Werkvertrag mit einem Kunden alles regeln? Mind. 8 Punkte.', model: '1) Vertragsparteien (vollständige Daten). 2) Leistungsgegenstand (was genau, Spezifikation, evtl. Briefing als Anhang). 3) Liefertermine und Meilensteine. 4) Vergütung (Pauschal oder Stundensatz, Zahlungsplan, Spesen). 5) Nutzungsrechte (Umfang, exklusiv?, Bereich, Dauer). 6) Korrekturschleifen (Anzahl inklusiv, weitere kostenpflichtig). 7) Mitwirkungspflichten Kunde (Material, Feedback-Fristen). 8) Haftung + Haftungsausschluss (z.B. für Bilder, deren Quelle vom Kunden kommt). 9) Geheimhaltung. 10) Kündigung + Rücktritt. 11) Eigentumsvorbehalt (Werke gehen erst mit voller Zahlung über). 12) Gerichtsstand. 13) Schriftform.', points: 10 },
      { type: 'open', q: 'AVV (Auftragsverarbeitungs-Vertrag) – wann brauchst du als Mediengestalter einen?', model: 'Bei JEDEM Dienstleister, der für DICH personenbezogene Daten verarbeitet. Beispiele: 1) Hosting-Provider (deine Website mit Kontaktformular). 2) Newsletter-Tool (Mailchimp etc.). 3) Cloud-Speicher (Dropbox, Google Drive – Achtung Drittland-Transfer!). 4) Buchhaltungs-Software in der Cloud. 5) Externer Datenschutzbeauftragter. \nUmgekehrt: Wenn DU für Kunden Daten verarbeitest (z.B. Kunden-CRM-System einrichten und dabei Daten siehst), brauchst DU mit Kunde einen AVV.\nInhalte gem. Art. 28 DSGVO: Gegenstand, Dauer, Art, Zweck, Datenarten, Pflichten, TOMs, Subunternehmer-Regelung, Löschung nach Vertragsende.', points: 10 },
      { type: 'mc', q: 'Eine Bildagentur klagt, weil du ein Foto ohne Lizenz auf der Website eines Kunden eingebaut hast. Wer haftet?', options: ['Der Kunde, weil es seine Website ist', 'Du, als Mediengestalter, der eingebaut hat', 'Beide gesamtschuldnerisch je nach Vertrag', 'Niemand, da im Internet "frei verfügbar"'], correct: 2, points: 4, explanation: 'Beide haften – der Kunde als Betreiber, du als ausführender Gestalter. Wer welchen Teil trägt, regelt der Vertrag (z.B. Freistellungsklausel). Deshalb IMMER Lizenz prüfen + dokumentieren!' },
      { type: 'open', q: 'Was ist die KSK und für wen ist sie relevant?', model: 'KSK = Künstlersozialkasse. Für selbstständige Künstler und Publizisten, die überwiegend (>= 50% Einkommen) künstlerisch oder publizistisch tätig sind. Mediengestalter, Designer, Fotografen können dazu gehören.\nVorteil: KSK übernimmt 50% der Beiträge zur gesetzlichen Renten-, Kranken- und Pflegeversicherung – wie ein Arbeitgeber. Versicherter zahlt nur die andere Hälfte.\nVoraussetzungen: Künstlerische/publizistische Selbstständigkeit, Mindesteinkommen 3.900 €/Jahr (Ausnahme Berufsanfänger), keine Versicherung über andere Quelle.\nAntrag mit Tätigkeitsnachweisen, Auftragsbestätigungen. Prüfung kann dauern. Lohnt sich finanziell sehr!', points: 8 },
      { type: 'open', q: 'Wie kalkulierst du einen fairen Stundensatz als Selbstständiger? Schritte und Beispielrechnung.', model: '1) Wunsch-Brutto-Jahresgehalt definieren (z.B. 50.000 €). 2) Aufschlag für Selbstständigen-Risiko (Krankheit, Urlaub, Ausfall) ca. 50% → 75.000 €. 3) Zzgl. Betriebskosten (Software, Hardware, Büro, Versicherungen, Weiterbildung) z.B. 15.000 € → 90.000 €. 4) Zzgl. Steuern (variabel, ca. 25% Rückstellung) → 112.500 € Umsatz nötig. 5) Verfügbare produktive Stunden: 220 Arbeitstage × 8 h × 60% produktiv (Rest = Akquise/Buchhaltung/Pause) = 1.056 h.\n→ Stundensatz Netto: 112.500 / 1.056 ≈ 107 €. Üblich für erfahrene Mediengestalter: 70-120 € netto/h. Berufseinsteiger: 50-70 €.', points: 10 },
      { type: 'open', q: 'Du arbeitest mit einem freien Fotografen zusammen. Welche rechtlichen Aspekte musst du beim gemeinsamen Projekt beachten?', model: '1) Klärung Urheber- und Nutzungsrechte: Fotograf bleibt Urheber, du brauchst Nutzungslizenz. 2) Modell-Verträge / Property-Releases (für Personen + Privatgrundstücke). 3) Honorierung schriftlich (Pauschal oder pro Bild, Sonderhonorierung bei Plakatwerbung). 4) Bildnennung (§ 13 UrhG): Fotograf hat Recht auf Namensnennung – mit Kunde abstimmen. 5) Haftung bei Pannen (z.B. fehlende Einwilligung) klar verteilen. 6) Bei Auftrag im Namen des Endkunden: ggf. AVV bezüglich personenbezogener Daten in Bildern. 7) Schriftliche Vereinbarung empfohlen, mind. per E-Mail.', points: 10 },
      { type: 'open', q: 'Vorsteuerabzug: Was ist das? Wann macht es Sinn, kein Kleinunternehmer zu sein?', model: 'Vorsteuer = USt, die du selbst zahlst beim Einkauf (z.B. 19% auf neuen Mac). Als Regelbesteuerter kannst du diese vom Finanzamt zurückbekommen, indem du sie bei deiner USt-Voranmeldung gegenrechnest.\nBeispiel: Du kaufst Mac für 2.380 € (= 2.000 + 380 USt). Du verlangst beim Kunden 5.950 € (= 5.000 + 950 USt). Statt 950 € abzuführen, ziehst du die 380 € Vorsteuer ab → führst nur 570 € ab.\nKein Kleinunternehmer sinnvoll wenn: 1) Hohe Investitionen geplant. 2) Kunden überwiegend B2B (USt-Pflichtige). 3) Wachstum nahe der 22.000-€-Grenze. Nicht sinnvoll: bei kleinem Nebenverdienst mit Privatkunden.', points: 8 },
    ]
  },
];
